import datetime
import re

from taf.ul.bts_kpi_report_generator.Exception import KPIFailTimeFormat


class PMMeasurement(object):
    """
    Instance will create on one measurement
    """
    def __init__(self, start_time, interval=15):
        """

        :param start_time: Start time measurement
        :param interval: Time duration measurements in minutes
        """
        self.__start_time = self.__parse_start_time(start_time)
        self.__interval = int(interval)
        self.__parameters = {}
        self.__type_measurements = {}

    @property
    def start_time(self):
        """
        Getter return start_time in default format datetime
        :return: object datetime
        """
        return self.__start_time

    @property
    def interval(self):
        """
        Getter return time duration measurements in minutes
        :return: int, default 15
        """
        return self.__interval

    @property
    def parameters(self):
        """
        Getter return parameters in nested dictionary: {'counter': dict}
        Example: {'[M8001]': {'DN': '0'}, '[M8002]': {'DN1': '20', 'DN2': '40'}}
        :return: dict
        """
        return self.__parameters

    @property
    def type_measurements(self):
        """
        Getter return type_measurement in nested dictionary: {'type_measurement': list}
        Example: {'LTE_1': ['M01', 'M02'], 'LTE_2': ['M03']}
        :return: dict
        """
        return self.__type_measurements

    def __getitem__(self, item):
        """
        Simply use: PMMeasurement['M00'] instead PMMeasurement.parameters['M00']
        """
        return self.__parameters[item]

    def add_counter_to_measurement_type(self, measurement_type, counter):
        """
        Add measurement_type to dict: {'measurement_type': ['counter1', 'counter2']}
        :param measurement_type: name measurement type
        :param counter: M...
        """
        if measurement_type not in self.__type_measurements:
            self.__type_measurements[measurement_type] = []
        if counter not in self.__type_measurements[measurement_type]:
            self.__type_measurements[measurement_type].append(counter)

    def add_parameters_pmmeasurement(self, counter_name, counter_value, dn):
        """
        Method create dict with counter and name dn: {'[M01]': {'dn1': 10, 'dn2': 20}, '[M02]': {'dn3': 30}}
        :param counter_name: M...
        :param counter_value: value in float
        :param dn: name dn in string
        """
        parameters_tag_with_operator = '[{}]'.format(counter_name)
        if parameters_tag_with_operator in self.__parameters:
            self.__parameters[parameters_tag_with_operator][dn] = counter_value
        else:
            self.__parameters[parameters_tag_with_operator] = {dn: counter_value}

    def get_xlsx_formula(self, formula, object_kpi):
        """
        Method change counter name on value
        :param formula: formula for Excel with release
        :param object_kpi: LNCEl, ENB, BTS or other exception
        :return: formula with counter value and begin '=IFERROR(' and end ',"NA")' or ',0.00)'
        """
        formula = re.sub(r'PERIOD_DURATION', str(self.interval), formula)
        formula = re.sub(r'MEASUREMENT_DURATION', str(self.interval), formula)
        list_m_parameters = re.findall(r'(\[M\w*\])', formula)
        for m_parameteres in list_m_parameters:
            if m_parameteres in self.__parameters.keys():
                if object_kpi in ['BTS', 'ENB']:
                    formula = self.__get_bts_formula(m_parameteres, formula)
                else:
                    formula = self.__get_lncel_exception_formula(m_parameteres, formula, object_kpi)
        if '[' and ']' in formula:
            formula = re.sub(r'\[', ' ', formula)
            formula = re.sub(r'\]', ' ', formula)
            formula_xlsx = '=IFERROR({},"NA")'.format(formula)
        else:
            formula_xlsx = '=IFERROR({},0.00)'.format(formula)
        return formula_xlsx

    def __get_lncel_exception_formula(self, m_parameter, formula, type_object):
        """
        Method change counter name on value for LNCEL object and exceptions
        :param m_parameter: name counter: M...
        :param formula: formula for Excel with release
        :param type_object: LNCEL or exceptions, example: ETH
        :return: formula with sum value counter for this same objects
        """
        sum_counter = None
        for dn in self.__parameters[m_parameter]:
            regex = r'({})\D*'.format(type_object)
            find_dn = re.findall(regex, dn)
            if len(find_dn) > 0 and sum_counter is None:
                sum_counter = float(self.__parameters[m_parameter][dn])
            elif len(find_dn) > 0:
                sum_counter += float(self.__parameters[m_parameter][dn])
        if sum_counter is not None:
            formula = re.sub((self.__correct_m_parameter(m_parameter)), '({})'.format(sum_counter), formula)
        return formula

    def __get_bts_formula(self, m_parameter, formula):
        """
        Method change counter name on value for BTS/ENB
        :param m_parameter: name counter M...
        :param formula: formula for Excel with release
        :return:  formula with sum value counter for this same BTS/ENB
        """
        sum_counter = None
        for dn in self.__parameters[m_parameter]:
            if 'LNCEL' and 'NRCELL' not in dn and sum_counter is None:
                sum_counter = float(self.__parameters[m_parameter][dn])
            elif 'LNCEL' and 'NRCELL' not in dn:
                sum_counter += float(self.__parameters[m_parameter][dn])
        if sum_counter is not None:
            formula = re.sub((self.__correct_m_parameter(m_parameter)), '({})'.format(sum_counter), formula)
        return formula

    @staticmethod
    def __parse_start_time(start_time):
        """
        Method change string on datetime structure
        :param start_time: start_time is string parse with file
        """
        try:
            if 'T' in start_time:
                start_time = start_time[0:23]
                return datetime.datetime.strptime(start_time, '%Y-%m-%dT%H:%M:%S.%f')
            else:
                return datetime.datetime.strptime(start_time, '%Y-%m-%d %H:%M:%S')
        except ValueError:
            raise KPIFailTimeFormat('Fail format time')

    @staticmethod
    def __correct_m_parameter(m_parameter):
        """
        Add '\' before '[' or ']'
        :param m_parameter: M...
        :return: correct m_parameter
        """
        m_parameter = re.sub(r'\[', '\\[', m_parameter)
        m_parameter = re.sub(r'\]', '\\]', m_parameter)
        return m_parameter
